/// The config for a deck name, or the empty one for an unknown name.
///
/// Python: `DECK_DATA.get(deck, ("", {}))[1]`.
pub fn deck_config(deck: &str) -> &'static DeckConfig {
    DECK_DATA
        .iter()
        .find(|(name, _)| *name == deck)
        .map(|(_, config)| config)
        .unwrap_or(&DeckConfig::EMPTY)
}
